mapper.insert:
INSERT INTO t_notification (user_id,
                            type,
                            type_id,
                            detail_type,
                            detail_type_id)
VALUES ( #{userId}
       , #{type}
       , #{typeId}
       , #{detailType}
       , #{detailTypeId})

mapper.select:
SELECT *
FROM t_notification
WHERE user_id = #{userId}
  AND date_created > NOW()::TIMESTAMPTZ - interval '30 day'
ORDER BY date_created DESC;

mapper.update:
UPDATE t_notification
SET read_yn   = 'Y',
    date_read = NOW()::TIMESTAMPTZ
WHERE user_id = #{userId}
  AND read_yn = 'N';
